                className={`text-[11px] font-space font-bold transition-colors uppercase tracking-[0.2em] ${location.pathname === link.href ? 'text-cyan-500' : 'text-zinc-400 hover:text-cyan-500'}`}
              >
                {link.name}
              </Link>
            )
          ))}
          <button className="bg-cyan-500 hover:bg-white text-black font-bold py-2.5 px-6 rounded-none transition-all duration-300 transform hover:scale-105 active:scale-95 font-space text-[11px] uppercase tracking-widest shadow-[0_0_20px_rgba(6,182,212,0.3)]">
            Start a Project
          </button>
        </div>

        {/* Mobile Toggle */}
        <button 
          className="md:hidden text-white"
          onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
        >
          {isMobileMenuOpen ? <X size={28} /> : <Menu size={28} />}
        </button>
      </div>

      {/* Mobile Menu */}
      <div className={`fixed inset-0 bg-black z-50 transition-transform duration-500 ${isMobileMenuOpen ? 'translate-x-0' : 'translate-x-full'} md:hidden`}>
        <div className="flex flex-col h-full justify-center items-center space-y-8 p-6">
          <button 
            className="absolute top-8 right-8 text-white"
            onClick={() => setIsMobileMenuOpen(false)}
          >
            <X size={32} />
          </button>
          {navLinks.map((link) => (
            link.href.startsWith('/#') ? (
               <a 
                key={link.name} 
                href={link.href}
                onClick={handleLinkClick}
                className="text-3xl font-space font-bold text-white hover:text-cyan-500 transition-colors uppercase tracking-widest"
              >
                {link.name}
              </a>
            ) : (
              <Link
                key={link.name}
                to={link.href}
                onClick={handleLinkClick}
                className="text-3xl font-space font-bold text-white hover:text-cyan-500 transition-colors uppercase tracking-widest"
              >
                {link.name}
              </Link>
            )
          ))}
          <button className="mt-8 bg-cyan-500 text-black font-bold py-4 px-12 rounded-none font-space text-lg uppercase tracking-widest">
            Start a Project
          </button>
        </div>
      </div>
    </nav>
  );
};

