export default App;

import React, { useState, useEffect } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { Menu, X } from 'lucide-react';

const Navbar: React.FC = () => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const location = useLocation();

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  useEffect(() => {
    setIsMobileMenuOpen(false);
  }, [location]);

  const navLinks = [
    { name: 'Strategy', href: '/#strategy' },
    { name: 'Technology', href: '/#technology' },
    { name: 'Creative', href: '/#creative' },
    { name: 'Industries', href: '/#industries' },
    { name: 'Founder', href: '/founder' },
  ];

  const handleLinkClick = () => {
    setIsMobileMenuOpen(false);
  };

  return (
    <nav className={`fixed top-0 left-0 w-full z-[100] transition-all duration-500 ${isScrolled ? 'bg-black/80 backdrop-blur-xl border-b border-white/10 py-4' : 'bg-transparent py-8'}`}>
      <div className="max-w-7xl mx-auto px-6 flex justify-between items-center">
        <Link to="/" onClick={() => window.scrollTo({top: 0, behavior: 'smooth'})} className="group flex items-center space-x-2">
          <span className="font-space font-bold text-2xl tracking-tighter text-white">COEXIN</span>
          <span className="font-space font-light text-2xl text-cyan-500 group-hover:text-white transition-colors duration-300">BRANDCOM</span>
        </Link>

        {/* Desktop Nav */}
        <div className="hidden md:flex items-center space-x-8">
          {navLinks.map((link) => (
            link.href.startsWith('/#') ? (
              <a 
                key={link.name} 
                href={link.href}
                className="text-[11px] font-space font-bold text-zinc-400 hover:text-cyan-500 transition-colors uppercase tracking-[0.2em]"
              >
                {link.name}
              </a>
            ) : (
              <Link
                key={link.name}
                to={link.href}
                className={`text-[11px] font-space font-bold transition-colors uppercase tracking-[0.2em] ${location.pathname === link.href ? 'text-cyan-500' : 'text-zinc-400 hover:text-cyan-500'}`}
              >
                {link.name}
              </Link>
            )
          ))}
          <Link 
            to="/contact"
            className="bg-cyan-500 hover:bg-white text-black font-bold py-2.5 px-6 rounded-none transition-all duration-300 transform hover:scale-105 active:scale-95 font-space text-[11px] uppercase tracking-widest shadow-[0_0_20px_rgba(6,182,212,0.3)]"
          >
            Start a Project
          </Link>
        </div>

        {/* Mobile Toggle */}
        <button 
          className="md:hidden text-white"
          onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
        >
          {isMobileMenuOpen ? <X size={28} /> : <Menu size={28} />}
        </button>
      </div>

      {/* Mobile Menu */}
      <div className={`fixed inset-0 bg-black z-50 transition-transform duration-500 ${isMobileMenuOpen ? 'translate-x-0' : 'translate-x-full'} md:hidden`}>
        <div className="flex flex-col h-full justify-center items-center space-y-8 p-6">
          <button 
            className="absolute top-8 right-8 text-white"
            onClick={() => setIsMobileMenuOpen(false)}
          >
            <X size={32} />
          </button>
          {navLinks.map((link) => (
            link.href.startsWith('/#') ? (
               <a 
                key={link.name} 
                href={link.href}
                onClick={handleLinkClick}
                className="text-3xl font-space font-bold text-white hover:text-cyan-500 transition-colors uppercase tracking-widest"
              >
                {link.name}
              </a>
            ) : (
              <Link
                key={link.name}
                to={link.href}
                onClick={handleLinkClick}
                className="text-3xl font-space font-bold text-white hover:text-cyan-500 transition-colors uppercase tracking-widest"
              >
                {link.name}
              </Link>
            )
          ))}
          <Link 
            to="/contact"
            onClick={handleLinkClick}
            className="mt-8 bg-cyan-500 text-black font-bold py-4 px-12 rounded-none font-space text-lg uppercase tracking-widest"
          >
            Start a Project
          </Link>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;

import React, { useState, useEffect } from 'react';
import { ArrowRight, ArrowLeft, Check, Brain, Zap, Cpu, BarChart3, Edit, Send } from 'lucide-react';

const serviceOptions = [
  { name: 'Strategy', icon: Brain, description: 'Market research, brand architecture, and growth mapping.' },
  { name: 'Tactics', icon: Zap, description: 'Omnichannel marketing, content ecosystems, and performance media.' },
  { name: 'Software', icon: Cpu, description: 'Custom platforms, UI/UX engineering, and systems integration.' },
  { name: 'Analytics', icon: BarChart3, description: 'Data science, BI dashboards, and full-funnel attribution.' },
];

const budgetOptions = ['< $5,000', '$5,000 - $15,000', '$15,000 - $50,000', '$50,000+'];
const timelineOptions = ['< 1 Month', '1-3 Months', '3-6 Months', '6+ Months'];

const ContactPage: React.FC = () => {
  const [step, setStep] = useState(1);
  const [formData, setFormData] = useState({
    services: [] as string[],
    description: '',
    budget: '',
    timeline: '',
    name: '',
    company: '',
    email: '',
  });
  const [submitted, setSubmitted] = useState(false);

  useEffect(() => {
    window.scrollTo(0, 0);
  }, []);

  const handleServiceToggle = (serviceName: string) => {
    setFormData(prev => ({
      ...prev,
      services: prev.services.includes(serviceName)
        ? prev.services.filter(s => s !== serviceName)
        : [...prev.services, serviceName],
    }));
  };

  const handleNext = () => setStep(s => Math.min(s + 1, 4));
  const handleBack = () => setStep(s => Math.max(s - 1, 1));
  const goToStep = (stepNumber: number) => setStep(stepNumber);

  const handleSubmit = () => {
    const subject = `Project Inquiry: ${formData.services.join(', ')} for ${formData.company || formData.name}`;
    const body = `
A new project inquiry has been submitted through the Coexin Brandcom website.

--- USER REQUIREMENTS ---

SERVICES OF INTEREST:
${formData.services.join('\n- ')}

PROJECT DESCRIPTION:
${formData.description || 'Not provided.'}

ESTIMATED BUDGET:
${formData.budget || 'Not specified.'}

EXPECTED TIMELINE:
${formData.timeline || 'Not specified.'}


--- CONTACT INFORMATION ---

NAME: ${formData.name}
COMPANY: ${formData.company || 'Not provided.'}
EMAIL: ${formData.email}

---------------------------
This email was auto-generated from the interactive contact form.
    `;
    window.location.href = `mailto:iroshan@coexinbrand.com?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
    setSubmitted(true);
  };

  const ProgressTracker = () => (
    <div className="flex items-center justify-center space-x-4 md:space-x-8 mb-16">
      {[1, 2, 3, 4].map(stepNum => (
        <div key={stepNum} className="flex items-center space-x-2 text-xs font-bold uppercase tracking-widest cursor-pointer" onClick={() => (stepNum < step ? goToStep(stepNum) : {})}>
          <div className={`w-8 h-8 rounded-full flex items-center justify-center font-space transition-all duration-300 ${step >= stepNum ? 'bg-cyan-500 text-black' : 'bg-white/5 text-zinc-500 border border-white/10'}`}>
            {step > stepNum ? <Check size={16} /> : stepNum}
          </div>
          <span className={`hidden md:block transition-colors ${step >= stepNum ? 'text-white' : 'text-zinc-600'}`}>
            {['Services', 'Scope', 'Contact', 'Review'][stepNum - 1]}
          </span>
        </div>
      ))}
    </div>
  );

  const renderContent = () => {
    if (submitted) {
      return (
        <div className="text-center animate-fade-in">
          <div className="w-24 h-24 mx-auto mb-8 bg-cyan-500/10 border-2 border-cyan-500 rounded-full flex items-center justify-center">
            <Send size={40} className="text-cyan-500" />
          </div>
          <h2 className="font-space text-4xl font-bold text-white mb-4">Inquiry Sent!</h2>
          <p className="text-zinc-400 max-w-md mx-auto text-lg leading-relaxed">
            Your email client has been opened with your project details. Please review and send it. We'll be in touch within 24 hours.
          </p>
        </div>
      );
    }

    switch(step) {
      case 1:
        return (
          <div className="animate-fade-in">
            <h2 className="font-space text-3xl font-bold text-white mb-2 text-center">What can we help you with?</h2>
            <p className="text-zinc-400 mb-12 text-center">Select one or more services that align with your project goals.</p>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {serviceOptions.map(({name, icon: Icon, description}) => (
                <div key={name} onClick={() => handleServiceToggle(name)}
                  className={`p-6 border transition-all duration-300 cursor-pointer group ${formData.services.includes(name) ? 'bg-cyan-500 border-cyan-500' : 'bg-white/5 border-white/10 hover:border-cyan-500/50'}`}>
                  <div className="flex items-start justify-between">
                    <div>
                      <Icon size={24} className={`mb-4 transition-colors ${formData.services.includes(name) ? 'text-black' : 'text-cyan-500'}`} />
                      <h3 className={`font-space text-xl font-bold transition-colors ${formData.services.includes(name) ? 'text-black' : 'text-white'}`}>{name}</h3>
                      <p className={`text-sm mt-2 transition-colors ${formData.services.includes(name) ? 'text-black/70' : 'text-zinc-500'}`}>{description}</p>
                    </div>
                    <div className={`w-6 h-6 rounded-full border-2 flex-shrink-0 mt-1 flex items-center justify-center ${formData.services.includes(name) ? 'border-black bg-black' : 'border-zinc-600 group-hover:border-cyan-500'}`}>
                      {formData.services.includes(name) && <Check size={14} className="text-cyan-500" />}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        );
      case 2:
        return (
          <div className="animate-fade-in">
            <h2 className="font-space text-3xl font-bold text-white mb-2 text-center">Tell us about the project.</h2>
            <p className="text-zinc-400 mb-12 text-center">Give us a brief overview of what you're looking to achieve.</p>
            <div className="space-y-8">
              <div>
                <label className="font-space text-sm font-bold text-zinc-400 tracking-widest uppercase" htmlFor="description">Project Description</label>
                <textarea id="description" rows={5} value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})}
                  className="w-full mt-2 p-4 bg-white/5 border border-white/10 text-white focus:ring-2 focus:ring-cyan-500 focus:outline-none transition-all"
                  placeholder="e.g., We need to build a new e-commerce platform for our premium spice brand..." />
              </div>
              <div>
                <label className="font-space text-sm font-bold text-zinc-400 tracking-widest uppercase mb-4 block">Estimated Budget</label>
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                  {budgetOptions.map(option => (
                    <button key={option} onClick={() => setFormData({...formData, budget: option})}
                      className={`p-4 text-center font-space font-bold border transition-all ${formData.budget === option ? 'bg-cyan-500 text-black border-cyan-500' : 'bg-transparent text-white border-white/20 hover:border-cyan-500'}`}>
                      {option}
                    </button>
                  ))}
                </div>
              </div>
              <div>
                <label className="font-space text-sm font-bold text-zinc-400 tracking-widest uppercase mb-4 block">Expected Timeline</label>
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                  {timelineOptions.map(option => (
                    <button key={option} onClick={() => setFormData({...formData, timeline: option})}
                      className={`p-4 text-center font-space font-bold border transition-all ${formData.timeline === option ? 'bg-cyan-500 text-black border-cyan-500' : 'bg-transparent text-white border-white/20 hover:border-cyan-500'}`}>
                      {option}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          </div>
        );
      case 3:
        return (
          <div className="animate-fade-in">
            <h2 className="font-space text-3xl font-bold text-white mb-2 text-center">Finally, how can we reach you?</h2>
            <p className="text-zinc-400 mb-12 text-center">We respect your privacy and will not share your information.</p>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="font-space text-sm font-bold text-zinc-400 tracking-widest uppercase" htmlFor="name">Full Name*</label>
                <input type="text" id="name" required value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})}
                  className="w-full mt-2 p-4 bg-white/5 border border-white/10 text-white focus:ring-2 focus:ring-cyan-500 focus:outline-none transition-all" />
              </div>
              <div>
                <label className="font-space text-sm font-bold text-zinc-400 tracking-widest uppercase" htmlFor="company">Company</label>
